  ).length;
  const connectionRate =
    totalClients > 0 ? (connectedClients / totalClients) * 100 : 0;
  const avgCpuUsage = state.metrics?.system?.cpu_usage || 0;
  const avgMemoryUsage = state.metrics?.system?.memory_usage || 0;

  const [isLoaded, setIsLoaded] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => setIsLoaded(true), 100);
    return () => clearTimeout(timer);
  }, []);

  return (
    <div className="space-y-8">
      {/* Quick Stats */}
      <div
        className={`grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 transition-all duration-700 ${
