        <QuickStat
          title="Активні клієнти"
          value={connectedClients}
          subtitle={`з ${totalClients} загалом`}
          icon="👥"
          trend={{
            value: `${connectionRate.toFixed(0)}% онлайн`,
            isPositive: connectionRate > 50,
          }}
          color="blue"
        />

        <QuickStat
          title="Навантаження CPU"
          value={`${Math.round(avgCpuUsage)}%`}
          subtitle="Середнє використання"
          icon="🖥️"
          trend={{
            value: avgCpuUsage > 70 ? "Високе" : "Нормальне",
            isPositive: avgCpuUsage <= 70,
          }}
          color={avgCpuUsage > 70 ? "red" : "green"}
        />

        <QuickStat
          title="Використання пам'яті"
          value={`${Math.round(avgMemoryUsage)}%`}
          subtitle="Оперативна пам'ять"
          icon="💾"
          trend={{
            value: avgMemoryUsage > 80 ? "Критично" : "Стабільно",
            isPositive: avgMemoryUsage <= 80,
          }}
          color={avgMemoryUsage > 80 ? "red" : "green"}
